"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[8911],{8671(a){a.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/AndroidCameraParameters/id/","label":"Ikhtisar Aplikasi","docId":"overview","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/development","label":"Dokumentasi Pengembang","docId":"development","unlisted":false},{"type":"category","label":"Mastering Android Camera2 API","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/AndroidCameraParameters/id/camera2/welcome-to-android-camera2","label":"Bab 1: Selamat Datang di Android Camera2","docId":"camera2/welcome-to-android-camera2","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/understanding-smartphone-cameras","label":"Bab 2: Memahami Kamera Smartphone","docId":"camera2/understanding-smartphone-cameras","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/what-can-modern-smartphone-cameras-do","label":"Bab 3: Fotografi Smartphone Modern","docId":"camera2/what-can-modern-smartphone-cameras-do","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/exploring-your-phones-camera","label":"Bab 4: Jelajahi Ponsel Anda Sendiri","docId":"camera2/exploring-your-phones-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/creating-your-first-camera2-project","label":"Bab 5: Membuat Proyek Camera2 Pertama Anda","docId":"camera2/creating-your-first-camera2-project","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/discovering-cameras","label":"Bab 6: Menemukan Kamera","docId":"camera2/discovering-cameras","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/opening-a-camera","label":"Bab 7: Membuka Kamera","docId":"camera2/opening-a-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/showing-camera-preview","label":"Bab 8: Menampilkan Pratinjau Kamera","docId":"camera2/showing-camera-preview","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/taking-photos","label":"Bab 9: Mengambil Foto","docId":"camera2/taking-photos","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/the-camera2-pipeline","label":"Bab 10: Pipeline Camera2","docId":"camera2/the-camera2-pipeline","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/capture-types","label":"Bab 11: Jenis Pengambilan Gambar","docId":"camera2/capture-types","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/cameracharacteristics-deep-dive","label":"Bab 12: Pembahasan Mendalam CameraCharacteristics","docId":"camera2/cameracharacteristics-deep-dive","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/exposure","label":"Bab 13: Eksposur","docId":"camera2/exposure","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/manual-exposure-in-camera2","label":"Bab 14: Eksposur Manual di Camera2","docId":"camera2/manual-exposure-in-camera2","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/focus","label":"Bab 15: Fokus","docId":"camera2/focus","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/white-balance-and-color","label":"Bab 16: Keseimbangan Putih & Warna","docId":"camera2/white-balance-and-color","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/3a-pipeline","label":"Bab 17: Pipeline 3A","docId":"camera2/3a-pipeline","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/raw-photography","label":"Bab 18: Fotografi RAW","docId":"camera2/raw-photography","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/high-speed-video","label":"Bab 19: Video Kecepatan Tinggi","docId":"camera2/high-speed-video","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/multi-camera","label":"Bab 20: Multi-Kamera","docId":"camera2/multi-camera","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/hdr-and-ultra-hdr","label":"Bab 21: HDR & Ultra HDR","docId":"camera2/hdr-and-ultra-hdr","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/camera-extensions","label":"Bab 22: Ekstensi Kamera","docId":"camera2/camera-extensions","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/zero-shutter-lag-and-reprocessing","label":"Bab 23: Zero Shutter Lag & Pemrosesan Ulang","docId":"camera2/zero-shutter-lag-and-reprocessing","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/camerax","label":"Bab 24: CameraX","docId":"camera2/camerax","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/native-camera-development","label":"Bab 25: Pengembangan Kamera Native","docId":"camera2/native-camera-development","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/asynchronous-camera-programming","label":"Bab 26: Pemrograman Kamera Asinkron","docId":"camera2/asynchronous-camera-programming","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/camera-testing","label":"Bab 27: Pengujian Kamera","docId":"camera2/camera-testing","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/camera2-architecture","label":"Bab 28: Arsitektur Camera2","docId":"camera2/camera2-architecture","unlisted":false},{"type":"link","href":"/AndroidCameraParameters/id/camera2/camera-metadata-encyclopedia","label":"Ensiklopedia Metadata Kamera","docId":"camera2/camera-metadata-encyclopedia","unlisted":false}],"href":"/AndroidCameraParameters/id/category/mastering-android-camera2-api"},{"type":"link","href":"/AndroidCameraParameters/id/data-safety","label":"Panduan Keamanan Data","docId":"data-safety","unlisted":false}]},"docs":{"camera2/3a-pipeline":{"id":"camera2/3a-pipeline","title":"Bab 17: Pipeline 3A","description":"Orkestrasikan Auto Exposure (AE), Auto Focus (AF), dan Auto White Balance (AWB) ke dalam urutan pengambilan foto diam yang andal. Pelajari pemicu pra-pengambilan (precapture trigger), mode lampu kilat, mesin status AE/AF, dan bangun kode Kotlin kualitas produksi yang mengoordinasikan ketiga A tersebut sebelum setiap bidikan.","sidebar":"tutorialSidebar"},"camera2/asynchronous-camera-programming":{"id":"camera2/asynchronous-camera-programming","title":"Bab 26: Pemrograman Kamera Asinkron","description":"Jinakkan callback hell Camera2 menggunakan coroutine Kotlin dan Flow. Pelajari suspendCancellableCoroutine untuk operasi satu kali (openCamera, createCaptureSession, capture), callbackFlow untuk aliran ImageReader dan CaptureResult yang berkelanjutan, operator combine untuk UI reaktif, dan pola keamanan thread untuk mencegah ANR dan deadlock.","sidebar":"tutorialSidebar"},"camera2/camera-extensions":{"id":"camera2/camera-extensions","title":"Bab 22: Ekstensi Kamera","description":"Gunakan CameraExtensionSession untuk fotografi komputasional yang dipercepat OEM: mode Malam, mode potret Bokeh, ekstensi HDR, Retouch Wajah, dan mode Otomatis. Kueri CameraExtensionCharacteristics, kelola latensi, dan bandingkan arsitektur Sesi Standar vs Sesi Ekstensi.","sidebar":"tutorialSidebar"},"camera2/camera-metadata-encyclopedia":{"id":"camera2/camera-metadata-encyclopedia","title":"Ensiklopedia Metadata Kamera","description":"Panduan referensi lengkap untuk semua kunci metadata CameraCharacteristics penting termasuk kategori Sensor, Lensa, Kontrol, Scaler, Permintaan, Lampu Kilat, JPEG, Statistik, dan Info.","sidebar":"tutorialSidebar"},"camera2/camera-testing":{"id":"camera2/camera-testing","title":"Bab 27: Pengujian Kamera","description":"Panduan pengujian kamera Android yang lengkap. Pahami Camera ITS (Image Test Suite), apa yang divalidasi OEM sebelum pengiriman (kombinasi fitur, pengujian adegan, fusi sensor), pengujian manual CTS Verifier, dan cara menulis pengujian instrumentasi Anda sendiri dengan mock Mockito dan pengujian tingkat perangkat keras berparameter yang berjalan di CI.","sidebar":"tutorialSidebar"},"camera2/camera2-architecture":{"id":"camera2/camera2-architecture","title":"Bab 28: Arsitektur Camera2","description":"Final arsitektur agung Camera2. Telusuri seluruh tumpukan dari aplikasi Kotlin Anda turun melalui Binder IPC, Framework, CameraService di native, Camera3Device, HAL3 dengan camera3_device_t, driver kernel V4L2, dan akhirnya sensor fisik, ISP, lensa VCM, dan perangkat keras lampu kilat. Termasuk persyaratan Treble HAL, pembungkus LEGACY HAL1, dan CameraDeviceSetup Android 15. Peta perjalanan pembaca lengkap ke lapisan-lapisan.","sidebar":"tutorialSidebar"},"camera2/cameracharacteristics-deep-dive":{"id":"camera2/cameracharacteristics-deep-dive","title":"Bab 12: Pembahasan Mendalam CameraCharacteristics","description":"Kuasai CameraCharacteristics \u2014 metadata statis tidak berubah yang menjelaskan setiap kamera sebelum Anda membukanya. Tingkat perangkat keras (LEGACY, LIMITED, FULL, LEVEL_3, EXTERNAL), flag kemampuan, pengorganisasian kunci metadata, dan kueri kemampuan saat runtime.","sidebar":"tutorialSidebar"},"camera2/camerax":{"id":"camera2/camerax","title":"Bab 24: CameraX","description":"Kuasai CameraX, pustaka kamera sadar-siklus-hidup milik Jetpack yang membungkus Camera2. Pelajari arsitektur UseCase, Camera2Interop untuk menyuntikkan parameter manual, dan kerangka kerja keputusan untuk memilih CameraX vs Camera2.","sidebar":"tutorialSidebar"},"camera2/capture-types":{"id":"camera2/capture-types","title":"Bab 11: Jenis Pengambilan Gambar","description":"Pelajari tiga jenis pengambilan gambar Camera2 \u2014 satu kali (capture), burst (captureBurst), dan berulang (setRepeatingRequest) \u2014 ditambah template bawaan (TEMPLATE_PREVIEW, TEMPLATE_STILL_CAPTURE, TEMPLATE_RECORD, dan lainnya).","sidebar":"tutorialSidebar"},"camera2/creating-your-first-camera2-project":{"id":"camera2/creating-your-first-camera2-project","title":"Bab 5: Membuat Proyek Camera2 Pertama Anda","description":"Siapkan proyek Android Camera2 lengkap dari awal. Pelajari tentang izin kamera, inisialisasi CameraManager, threading latar belakang dengan HandlerThread, dan konfigurasi proyek yang diperlukan untuk akselerasi perangkat keras TextureView.","sidebar":"tutorialSidebar"},"camera2/discovering-cameras":{"id":"camera2/discovering-cameras","title":"Bab 6: Menemukan Kamera","description":"Hitung dan kueri setiap kamera pada perangkat Android menggunakan CameraCharacteristics. Pelajari semantik ID kamera, arah hadap lensa (depan/belakang/eksternal), kamera USB OTG eksternal, dan hierarki tingkat perangkat keras dari LEGACY hingga LEVEL_3.","sidebar":"tutorialSidebar"},"camera2/exploring-your-phones-camera":{"id":"camera2/exploring-your-phones-camera","title":"Bab 4: Jelajahi Ponsel Anda Sendiri","description":"Gunakan aplikasi pendamping Android Camera Parameters untuk memeriksa perangkat Anda sendiri. Pelajari cara membaca ID Kamera, memeriksa Tingkat Perangkat Keras, menghitung kamera, memeriksa format yang didukung, frame rate, rentang zoom, dan kemampuan RAW.","sidebar":"tutorialSidebar"},"camera2/exposure":{"id":"camera2/exposure","title":"Bab 13: Eksposur","description":"Kuasai dasar-dasar eksposur fotografi\u2014Segitiga Eksposur dari ISO, kecepatan rana, dan bukaan (aperture). Pahami stop EV, aturan Sunny 16, dan bagaimana berbagai kombinasi menciptakan eksposur yang sama dengan pertukaran kreatif.","sidebar":"tutorialSidebar"},"camera2/focus":{"id":"camera2/focus","title":"Bab 15: Fokus","description":"Kuasai fokus otomatis dan manual di Android Camera2. Pahami mode AF, mesin status AF, urutan pemicu-dan-ambil satu kali, fokus manual dengan dioptri LENS_FOCUS_DISTANCE, jarak hiperfokal, dan membangun slider SeekBar fokus di Kotlin.","sidebar":"tutorialSidebar"},"camera2/hdr-and-ultra-hdr":{"id":"camera2/hdr-and-ultra-hdr","title":"Bab 21: HDR & Ultra HDR","description":"Implementasikan video HDR10 dan HLG via DynamicRangeProfiles, dan foto diam JPEG_R Android 14 (Ultra HDR ISO 21496-1) dengan arsitektur SDR-primary + gain-map untuk foto rentang dinamis tinggi yang kompatibel ke belakang","sidebar":"tutorialSidebar"},"camera2/high-speed-video":{"id":"camera2/high-speed-video","title":"Bab 19: Video Kecepatan Tinggi","description":"Bangun pengambilan gambar gerak lambat 120fps dan 240fps dengan CameraConstrainedHighSpeedCaptureSession, createHighSpeedRequestList, dan rentang FPS StreamConfigurationMap dalam API Android Camera2","sidebar":"tutorialSidebar"},"camera2/manual-exposure-in-camera2":{"id":"camera2/manual-exposure-in-camera2","title":"Bab 14: Eksposur Manual di Camera2","description":"Ambil kendali kreatif penuh atas eksposur dengan API Android Camera2. Pelajari cara menonaktifkan auto-exposure, menyetel ISO manual melalui SENSOR_SENSITIVITY, mengontrol kecepatan rana dalam nanodetik dengan SENSOR_EXPOSURE_TIME, dan bangun contoh Kotlin yang berfungsi untuk timelapse, eksposur panjang, dan bracketing.","sidebar":"tutorialSidebar"},"camera2/multi-camera":{"id":"camera2/multi-camera","title":"Bab 20: Multi-Kamera","description":"Jelajahi perangkat multi-kamera logis Android 9+, ID kamera fisik, sinkronisasi sensor APPROXIMATE vs CALIBRATED, peralihan zoom yang mulus, dan pengambilan fisik ganda simultan melalui OutputConfiguration.setPhysicalCameraId() dalam API Camera2","sidebar":"tutorialSidebar"},"camera2/native-camera-development":{"id":"camera2/native-camera-development","title":"Bab 25: Pengembangan Kamera Native","description":"Beralih ke native dengan tumpukan kamera NDK Android. Gunakan ACameraManager untuk membuka kamera dari C++, hubungkan memori AHardwareBuffer secara langsung sebagai tekstur Vulkan untuk AR tanpa salinan, dan pahami interop OpenGL/Vulkan untuk pipeline 60fps. Termasuk konteks migrasi EVS otomotif.","sidebar":"tutorialSidebar"},"camera2/opening-a-camera":{"id":"camera2/opening-a-camera","title":"Bab 7: Membuka Kamera","description":"Bangun koneksi langsung ke perangkat kamera menggunakan openCamera(). Kuasai siklus hidup CameraDevice, implementasikan StateCallback dengan onOpened/onDisconnected/onError, integrasikan buka/tutup dengan Activity onPause/onResume, dan tangani setiap kode kesalahan CameraAccessException dengan kontrol konkurensi berbasis Semaphore.","sidebar":"tutorialSidebar"},"camera2/raw-photography":{"id":"camera2/raw-photography","title":"Bab 18: Fotografi RAW","description":"Kuasai format RAW_SENSOR, pembuatan file DNG dengan DngCreator, pola Bayer, dan pengambilan RAW+JPEG secara simultan dalam API Android Camera2","sidebar":"tutorialSidebar"},"camera2/showing-camera-preview":{"id":"camera2/showing-camera-preview","title":"Bab 8: Menampilkan Pratinjau Kamera","description":"Rendarkan bingkai kamera langsung di layar menggunakan TextureView, SurfaceTexture, Surface, dan CameraCaptureSession. Implementasikan SurfaceTextureListener, koreksi aspek rasio dengan transformasi Matrix di configureTransform, bangun CaptureRequest TEMPLATE_PREVIEW, dan mulai aliran pratinjau dengan setRepeatingRequest.","sidebar":"tutorialSidebar"},"camera2/taking-photos":{"id":"camera2/taking-photos","title":"Bab 9: Mengambil Foto","description":"Ambil foto diam berkualitas tinggi dengan Camera2 menggunakan ImageReader (JPEG), pemicu AE pra-pengambilan, dan mesin status CaptureCallback. Simpan foto dengan MediaStore yang kompatibel dengan Scoped Storage (Android 10+) dan FileOutputStream lama, selalu ingat untuk menutup buffer Image.","sidebar":"tutorialSidebar"},"camera2/the-camera2-pipeline":{"id":"camera2/the-camera2-pipeline","title":"Bab 10: Pipeline Camera2","description":"Pembahasan mendalam tentang arsitektur pipeline Camera2 \u2014 CaptureRequest, CaptureResult, antrean permintaan, callback hasil, dan alur ujung-ke-ujung dari pengiriman permintaan hingga pemrosesan HAL dan hasil.","sidebar":"tutorialSidebar"},"camera2/understanding-smartphone-cameras":{"id":"camera2/understanding-smartphone-cameras","title":"Bab 2: Memahami Kamera Smartphone","description":"Jelajahi perangkat keras modul kamera di dalam setiap smartphone: lensa, sensor gambar, prosesor ISP, perbedaan antara RAW dan JPEG, desain multi-kamera, dan perjalanan lengkap dari foton hingga foto yang disimpan.","sidebar":"tutorialSidebar"},"camera2/welcome-to-android-camera2":{"id":"camera2/welcome-to-android-camera2","title":"Bab 1: Selamat Datang di Android Camera2","description":"Pelajari mengapa Android Camera2 penting, perbandingannya dengan Camera1 dan CameraX, apa yang dimungkinkannya, dan apa yang akan Anda bangun dalam seri ini.","sidebar":"tutorialSidebar"},"camera2/what-can-modern-smartphone-cameras-do":{"id":"camera2/what-can-modern-smartphone-cameras-do","title":"Bab 3: Fotografi Smartphone Modern","description":"Tur fitur komputasional dan optik pada ponsel modern: HDR, bokeh potret, mode malam, gerak lambat, ultra-lebar, telefoto, makro, dan bagaimana fotografi komputasional menggabungkan perangkat keras dan perangkat lunak.","sidebar":"tutorialSidebar"},"camera2/white-balance-and-color":{"id":"camera2/white-balance-and-color","title":"Bab 16: Keseimbangan Putih & Warna","description":"Kontrol warna di Android Camera2 dengan preset Auto White Balance dan koreksi warna manual. Pelajari mode AWB, suhu warna (2000K\u201310000K), transformasi warna 3\xd73, COLOR_CORRECTION_GAINS, dan kode Kotlin untuk preset matahari terbenam nada hangat dan keseimbangan putih manual penuh.","sidebar":"tutorialSidebar"},"camera2/zero-shutter-lag-and-reprocessing":{"id":"camera2/zero-shutter-lag-and-reprocessing","title":"Bab 23: Zero Shutter Lag & Pemrosesan Ulang","description":"Bangun Zero Shutter Lag (ZSL) dengan buffering YUV/PRIVATE melingkar, CONTROL_CAPTURE_INTENT_ZERO_SHUTTER_LAG, sesi pengambilan gambar yang dapat diproses ulang via InputConfiguration, injeksi ulang bingkai ImageWriter, dan createReprocessCaptureRequest untuk pemrosesan ISP pasca-pengambilan yang berat. Juga mencakup switchToOffline() untuk kontinuitas pemrosesan latar belakang.","sidebar":"tutorialSidebar"},"data-safety":{"id":"data-safety","title":"Panduan Keamanan Data","description":"Praktik keamanan data dan privasi untuk aplikasi Android Camera Parameters. Pelajari tentang izin kamera dan bagaimana metadata perangkat keras ditangani.","sidebar":"tutorialSidebar"},"development":{"id":"development","title":"Dokumentasi Pengembang","description":"Arsitektur teknis aplikasi Android Camera Parameters, termasuk detail pola MVVM, struktur UI Jetpack Compose, dan panduan pengembangan.","sidebar":"tutorialSidebar"},"overview":{"id":"overview","title":"Ikhtisar Aplikasi","description":"Ikhtisar dasbor Android Camera Parameters dan fitur diagnostik utamanya termasuk deteksi level perangkat keras dan pelacakan fitur waktu nyata.","sidebar":"tutorialSidebar"}}}}')}}]);